import { readFileSync, rmSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { resolveManagedCargoTarget } from "./lib/target-root.mjs";

// Runtime is generated by Blueprint's canonical stager during packaging.
// Remove prior output before RightKit scans Cargo manifests so embedded eval
// fixtures are never mistaken for Membrane source workspaces.
rmSync(fileURLToPath(new URL("../src-tauri/runtime", import.meta.url)), { recursive: true, force: true });

const result = spawnSync("pnpm", ["exec", "right-release", "build", "--platform", "mac"], {
  cwd: fileURLToPath(new URL("../", import.meta.url)),
  env: process.env,
  stdio: "inherit",
});
if (result.error) throw result.error;
if (result.status !== 0) process.exit(result.status ?? 1);

const hub = fileURLToPath(new URL("../", import.meta.url));
const version = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")).version;
const targetRoot = resolveManagedCargoTarget(fileURLToPath(new URL("../src-tauri/Cargo.toml", import.meta.url)));
const dmg = `${targetRoot}/aarch64-apple-darwin/release/bundle/dmg/Membrane Hub_${version}_aarch64.dmg`;
run("xcrun", ["stapler", "staple", dmg]);
run("xcrun", ["stapler", "validate", dmg]);
run("spctl", ["-a", "-vv", "--type", "open", "--context", "context:primary-signature", dmg]);
run("pnpm", ["exec", "right-release", "mirror-root-artifact", "--file", dmg, "--package-root", hub]);

function run(command, args) {
  const outcome = spawnSync(command, args, { cwd: hub, env: process.env, stdio: "inherit" });
  if (outcome.error) throw outcome.error;
  if (outcome.status !== 0) throw new Error(`${command} failed with exit ${outcome.status}`);
}
